#!/usr/bin/env node
import fs from "fs";

const mech = {
  "1:main": `The laws of eruvin from the Torah. And in it are 3 seifim: From the Torah one is liable only for hotza'ah and hachnasah and throwing and passing from reshut ha-yachid to reshut ha-rabbim or from reshut ha-rabbim to reshut ha-yachid, and the Sages forbade from karmelit to reshut ha-yachid or to reshut ha-rabbim or from them to karmelit; but makom patur — it is permitted to remove and insert from it to reshut ha-yachid and to reshut ha-rabbim and from them into it; but one standing in reshut ha-yachid who removes or inserts or passes or throws to reshut ha-rabbim via makom patur, or the reverse, is liable; and similarly one should not stand on makom patur and take an object from the hand of one standing in reshut ha-rabbim and give it to one standing in reshut ha-yachid, or the reverse; and to exchange via makom patur in rabbinic domains — some forbid and some permit [and see below siman 372 seif 6]:`,
  "2:main": `From the Torah one is liable only for passing four amot in reshut ha-rabbim, and the Sages forbade passing four amot in karmelit and in the sea and in a valley — these are two types of karmelit — and it is permitted to move objects from one to the other within four amot:`,
  "3:main": `A karpef [meaning: a place enclosed by partitions without a ceiling, like a courtyard] more than beit se'ah that was not enclosed for dwelling — the Sages forbade moving objects in it except within four amot, and it is permitted to remove from it to another karmelit, such as a valley passing before it: {Rama: Therefore it is permitted to take a key from the karmelit before a garden to open and lock and return the key to it [Tur], provided there is not between them a threshold that is reshut ha-yachid — such as if it is ten [tefachim] high and four wide, or if it has two partitions from the sides that are four wide and a lintel over it four wide, for then it is reshut ha-yachid even though it is not ten high; however it is forbidden to insert from that threshold to reshut ha-yachid or the reverse, for we are concerned perhaps the roof will not be four, and then if the threshold is not three high it has the law of that which is before it; and even if it is three high, since all our domains are karmelit we say "a kind found its kind and was aroused," as explained in siman 345; and similarly if the roof is very wide and has no side partitions — its law is like the domain before it; and similarly our roofs protruding before houses — their law is like the domain before them [Hagahot Mordechai first chapter of Shabbat]:}`,
};

const small = {
  "baer-heitev:3:א": `Karpef. From the Torah it is full reshut ha-yachid; they only permitted moving objects from it to karmelit, for if it were forbidden they would say it is full reshut ha-yachid and come to move objects throughout it, and through this others would come to move objects in reshut ha-rabbim, for this resembles reshut ha-rabbim — Taz, see there:`,
  "baer-heitev:3:ב": `Therefore it is permitted. Meaning that even though the garden is reshut ha-yachid from the Torah, they did not forbid moving objects from it to karmelit — and this is exactly the law stated above:`,
  "baer-heitev:3:ג": `Two partitions. And regarding the third we say "the edge of the roof descends and seals" — Magen Avraham:`,
  "baer-heitev:3:ד": `Reshut ha-yachid. Meaning it is forbidden to insert there from the karmelit before it; if so it would be fitting to permit inserting from this threshold to reshut ha-yachid; nevertheless it is forbidden, lest it not be four wide and it will be karmelit; even if it is not four wide, since karmelit is before it — "a kind found its kind," etc.:`,
  "baer-heitev:3:ה": `Before it. Taz wrote: I have seen many stumble in those places where moving objects is forbidden for lack of an eruv, and the synagogue door faces the street with no room before the door, and a non-Jew brings the key — one must be careful that the shamash not take the key from his hand until he is with the non-Jew under the lintel over the door, lest there be four [tefachim] in the roof and it be reshut ha-yachid and he move objects from the karmelit before the synagogue into reshut ha-yachid; therefore he should take the key from him under the lintel, then open the lock, and not open the door until he removes the key, then open the door — lest there not be four in the roof outside the door, in which case it is karmelit and he inserts from karmelit to reshut ha-yachid; therefore he should first remove the key and give it to the non-Jew or hide it in the door at its bottom or at its side. And a house whose door opens to karmelit must be careful not to move objects from the house outward except to the extent the door closes there and no more, lest the outer part not be four and it be karmelit and he move from reshut ha-yachid to karmelit; it is fitting for that congregation to make some room before the door that is reshut ha-yachid and have the non-Jew bring the key there, and then there is no concern. And it is implied in Mordechai that there is permission to bring via a minor the key, like via a non-Jew, since we have only karmelit which is rabbinic — end of his words:`,
  "baer-heitev:3:ו": `And similarly regarding roofs. Here is explained the doubt that many are uncertain about: a house before which, toward the street, a roof protrudes toward the street built underneath with boards called in foreign tongue "perliban" — what is their law, whether one may move objects there from the house; many err saying "the edge of the roof descends and seals" to there and the protruding side toward the street, and it is as if built to the ground; from here it is explicit that the law of what is under the roof is like the domain before them — Taz; and see Taz siman 365 s.k. 6 who wrote there in the name of Maharil that if the protrusion before the house has three partitions and a fourth of "the edge of the roof descends and seals" four wide, it is good to be stringent even in this — see there; and it requires study whether perliban helps, for it does not help unless the standing exceeds the breach, as written siman 362:`,
  "baer-heitev:3:ז": `Like the domain. The custom of women standing under the hollow of the door lintel to hide the key under the door even when the door is locked — the lintel is entirely outside; even though they are not instructed thus, nevertheless one need not protest — Eshel Avraham, siman 112:`,
  "beer-hagolah:1:א": `Shabbos 7 and 96`,
  "beer-hagolah:1:ב": `Braita there and 8`,
  "beer-hagolah:1:ג": `Braita there; and as the first Tanna; Rosh and Ran in chapter 14 and Rabbeinu Yonah`,
  "beer-hagolah:1:ד": `Braita there 7 and 8`,
  "beer-hagolah:1:ה": `Rosh in the name of Razah and Ra'avad agreed with them from what is in Eruvin chapter 7; and so wrote Rashba`,
  "beer-hagolah:1:ו": `Rif there and Rambam chapter 14 as the Mechaber wrote there; and so ruled the great teachers`,
  "beer-hagolah:2:_": `Shabbos 7`,
  "beer-hagolah:3:א": `Shabbos 6 and Eruvin 67 — it is full reshut ha-yachid`,
  "beer-hagolah:3:ב": `Eruvin there and 23`,
  "beer-hagolah:3:ג": `There chapter 7`,
  "beer-hagolah:3:ד": `See above siman 345 seif 6 and in what I noted there)`,
  "beur-hagra:1:א": `Siman 61 — from the Torah. 6a:`,
  "beur-hagra:1:ב": `And throwing and passing. 96a, 6a, 1a; Tosefta, etc.:`,
  "beur-hagra:1:ג": `And the Sages. There:`,
  "beur-hagra:1:ד": `But one standing, etc. And not like Ben Azai; and likewise the anonymous Mishna 91b disagrees with him; and in the last chapter it is strained in the Gemara regarding a long threshold — and Abaye says, etc. — see my comments; and they did not immediately establish it like Ben Azai; and that which R' Yochanan said and Ben Azai concedes regarding throwing — he does not hold like him, for Rabbah also does not hold like him, as written in Kesubos 31 and as Tosafos wrote there — see there:`,
  "beur-hagra:1:ה": `Some forbid. As Ravina wrote, Eruvin chapter 7b, and like R' Yochanan 76a and there 101b:`,
  "beur-hagra:1:ו": `And some permit. Like the first answer — only in corners — and like R' Yochanan and Abaye and R' Chanina and R' Ashi — all hold like the first version; Shabbos 101a — see Rashi s.v. "but," etc., and Tosafos s.v. "R' Yochanan," etc.; and it is difficult, etc.:`,
  "beur-hagra:2:א": `Siman 62 — from the Torah. 96b:`,
  "beur-hagra:2:ב": `And the Sages. 6a:`,
  "beur-hagra:2:ג": `And permitted. 8b it is, and its eruv in karmelit — Eruvin 67b, 101b, 90a — two, etc.:`,
  "beur-hagra:3:א": `Siman 63 — therefore. Tosafos there s.v. "and what," etc.:`,
  "beur-hagra:3:ב": `Provided. 101b — and if it has four, etc.:`,
  "beur-hagra:3:ג": `Or if there are. Meaning the door is one partition and another partition from the side — unlike one opposite the other, not as written siman 361 seif 2 in the gloss; and we say, etc.:`,
  "beur-hagra:3:ד": `That they are. For in less than four, even four partitions are not reshut ha-yachid, as written in Shabbos from the leniencies of reshut ha-yachid, etc.; and as I wrote siman 345 seif 9; and likewise regarding partitions, etc.:`,
  "beur-hagra:3:ה": `And a lintel, etc. As written siman 361 there in the gloss; and some say, etc.:`,
  "beur-hagra:3:ו": `And even if. Meaning it is makom patur, as in seif 9:`,
  "beur-hagra:3:ז": `Since. 40 — it refers specifically when it is three high; but without three, in any case it is like the domain before it, for it is not makom patur, as written there; but this is not so, since it has three partitions it is not reshut ha-rabbim and also not karmelit, as I wrote there, since it is not four, seif 9; and likewise regarding partitions; and even according to Rambam that with three partitions it is not reshut ha-yachid, nevertheless here it is not karmelit since it is less than four; and Tosafos Shabbos 9a s.v. "even though," etc., and there s.v. "within," etc. — and if you ask, etc., and one may say, etc.:`,
  "beur-hagra:3:ח": `And similarly if. As I wrote siman 345 seif 14 — and a roof that is covered:`,
  "beur-hagra:3:ט": `And similarly regarding roofs. Meaning even if there are partitions, "the edge of the roof descends and seals" does not apply since it slopes, as written siman 361 seif 2; and this is so even if the partitions are four wide, as written siman 345 seif 14 and corner projections, etc.; and as Tosafos wrote there s.v. "even though," etc.; or one may say entirely outside, etc.:`,
  "biur-halacha:1:_": `In rabbinic domains — see in Mishna Berurah what he wrote, meaning one standing on makom patur, etc. — know that according to what is explained at the end of the siman regarding makom patur standing next to karmelit — we say "a kind found its kind" and its law is like karmelit [and this is like the first view mentioned in the gloss at the end of siman 345 — see there] — one must explain the makom patur here that is ten high [and not four wide], for then according to all views we cannot consider it karmelit even though it is adjacent, for karmelit does not extend above ten; but if less than ten, even if not four wide, it has the law of karmelit according to that first view:`,
  "biur-halacha:3:א": `Karpef more than beit se'ah — see Magen Avraham that from the Torah it is full reshut ha-yachid, and as his words are explained in the Gemara Eruvin 67b — see there; and behold in the sugya there it is explained that even if it is the width of a kor or two korim it is still full reshut ha-yachid from the Torah for all matters. And know that Tosafos on daf 22b s.v. "lest" — a kor or two korim, but even a thousand korim is reshut ha-yachid; and that which the Gemara wonders there — in such a case even Babylon is enclosed by the Euphrates and everyone is enclosed by the ocean — implying that with partitions very far apart it is not called enclosed — Tosafos answer because partitions made not by human hands are not considered a partition to that extent; and even the Rabbis agree that people come and nullify the partition; and Ritva in the name of Ramban is not so — according to him that which the Gemara wonders regarding Babylon enclosed by the Euphrates is because the Gemara holds that with distant partitions there is no reason it should be as enclosed by partitions; and he wrote in the name of Ramban that whenever the partition is not visible to those standing in the middle and is not recognizable to them, it is not called a partition from the Torah; and he concludes that therefore that which we say on daf 67 "even a kor or two korim" is specifically in such a measure that at least the partition is visible to those standing in the middle, but not in very many — see Ritva; and see Rashba who also sided with Ritva, that from this sugya it is proven there is a measure for how much is called reshut ha-yachid; nevertheless he concludes with uncertainty — if so, how much is the measure; and it appears he was not satisfied to decide like Ramban's measure; but when we examine Ramban's own words in the sugya of a private city [from which Ritva took his view], it appears another way in his view: Ramban did not write there except regarding partitions standing by themselves like mountains and valleys; and on this he wrote that whenever they are very far apart so one does not find himself within the partitions, it is not called partitions — as proven from that case of Babylon enclosed by the Euphrates — see Ramban; and the sugya of daf 67 regarding a kor or two korim he did not bring at all in his words; and it may well be said he holds that there even a thousand korim, because there the partitions are made by human hands, even though lacking dwellings; and like Tosafos' view, except he argues with Tosafos: according to them specifically when it was a public thoroughfare in the middle and because people come and nullify the partition made by itself; but according to him even if there was no public thoroughfare in the middle — and like that case on daf 67 regarding karpef: if the partitions were made by themselves they do not help if the partitions were far apart and it would be only makom patur from the Torah; and especially according to what Ramban wrote there another second answer: "Or alternatively, when the partition does not obstruct and diminish the public at all, it has no status of a partition" — and this applies to the case of making posts by the ladder of Tyre and the ocean; it may certainly be said that regarding karpef Ramban agrees with Tosafos that even if very wide so the partition is not visible to those standing in the middle, it is reshut ha-yachid from the Torah, since it at least obstructs the public from passing there because of the enclosed partitions:`,
  "biur-halacha:3:ב": `And permitted to remove from it to another karmelit — know that it is implied from Tosafos Shabbos s.v. "even though" that likewise it is permitted to remove from a place that has three partitions — even though from the Torah it is full reshut ha-yachid — to karmelit, since in any case rabbinically they made it karmelit, like regarding karpef; afterward I found Beit Me'ir wrote thus from reasoning — and it is surprising he did not bring proof from those Tosafos:`,
  "biur-halacha:3:ג": `Two partitions from the sides, etc. — see Mishna Berurah; Magen Avraham challenged: behold at the end of siman 361 it is ruled that specifically the two partitions must be attached one to the other opposite one another — we do not say "the edge of the roof descends and seals"; and if the door is considered a partition, then one partition from the side suffices — see what he answered there; and in Eshel Avraham he answered: here, since it is not open to reshut ha-rabbim — on one side the garden door — even with two partitions opposite one another; and the Gra in his Biur wrote: in truth one partition from the side suffices, and the door is also considered a partition — thus there are two attached partitions; and so wrote Tosafos Shabbos — Rama only mentioned it as the manner of speech, but for the law one partition makes reshut ha-yachid, and for the other two partitions we say "the edge of the roof descends and seals" via the lintel above:`,
  "biur-halacha:3:ד": `And a lintel four wide — and in an alley opening: even if it is not entirely roofed, only the outer half is roofed, we say "the edge of the roof descends and seals" since there is a place of four from the edge of the roof to the door — the alley is upon it and combines with the alley and the beam permits it [and this is if the alley door were closed]; and if the opening is open, even if there is no place of four, it is considered inward [Magen Avraham] — it requires study, for behold Magen Avraham's words flow from the Gemara Shabbos 9, and there Tosafos explicitly state: if open to reshut ha-rabbim, even if the opening is closed it is inward when there is not four wide [and since for lechi they are lenient, open to reshut ha-rabbim when the opening is closed — all the more so for a beam]; therefore Magen Avraham deals with open to karmelit; nevertheless if the opening is open it is inward — and this contradicts Shulchan Aruch later siman 365 seif 4, which explicitly rules open to karmelit is forbidden under the beam; in truth from this sugya according to Tosafos and Rosh and also Rashi it is proven they hold like Ra'avad that under the beam is permitted even open to karmelit; if so it is surprising Magen Avraham was silent and did not mention that Shulchan Aruch contradicts this — it requires study:`,
  "biur-halacha:3:ה": `However forbidden, etc. — he is not speaking of the law of a garden; a garden has the law of karmelit — rather he means: even though we say when the mentioned threshold is by a garden it is forbidden to insert and remove from it to the garden because it is reshut ha-yachid and he moves objects from it to karmelit — one might think that if this threshold stands by full reshut ha-yachid it is permitted to insert and remove from it inward, for we are concerned, etc. [Mordechai's statement]:`,
  "biur-halacha:3:ו": `The law of that before it — see Mishna Berurah: if it is reshut ha-rabbim this place is nullified relative to it and also becomes reshut ha-rabbim; and in Biur HaGra it is proven that in this it does not become reshut ha-rabbim since it has partitions — see there; only where open to karmelit do we say "a kind found its kind," as Rama wrote afterward regarding three high:`,
  "biur-halacha:3:ז": `And similarly our roofs, etc. — the Gra wrote: in our roofs that slope, even if there are side partitions, it also does not help to permit inserting from there inward; even if the partitions are four wide — "the edge of the roof descends and seals" cannot apply since it slopes, as explained siman 361 seif 2; if so there are only three partitions, which is karmelit — see siman 362 there what we wrote:`,
  "biur-halacha:3:ח": `Protruding before the houses — see Mishna Berurah what we wrote in the name of the later authorities: a correction for this matter — make a doorway form on all three sides; and even though Taz in siman 365 wrote that even a doorway form does not help here because of concern for Rambam's view brought siman 362 seif 10 — all the later authorities [Eshel Avraham in the name of Ma'aneh Lashon, Tosafos Shabbos, Gra, Chayei Adam] brought as law to be lenient like Magen Avraham and Beit Me'ir; Beit Me'ir wrote that only according to Rambam is there leniency here — see his reason; and especially according to what we wrote siman 362 seif 10 in Mishna Berurah that up to ten amot one need not be stringent regarding breach greater than standing — thus those doorway forms from the sides are certainly full partitions, for they are not so wide; if so there are three complete partitions and only that side toward the street remains; and on one side, according to all views, a doorway form helps in every case, as we wrote there. And know that we did not cite Maharil brought in Magen Avraham because all the later authorities answered his words, as brought in Machatzit HaShekel; if the protruding roof is not sloped, one need not three doorway forms — two sides suffice, and on the third "the edge of the roof descends and seals":`,
  "chatam-sofer:1:_": `In Taz s.k. 27 it is implied in Mordechai that there is permission to bring via a minor — see what Pri Megadim wrote; and in responsa Chatam Sofer part 6 siman 13 [regarding a rabbi who ruled it permitted to tell girls in a place without an eruv to insert and remove everything needed for Shabbat, relying on what Mordechai brought in Taz; in his responsum he wrote to explain Taz's words that they certainly spoke only regarding a mitzvah matter; and likewise in Peri Megadim — but even for mitzvah need we do not permit piling a prohibition on a minor for our needs; he elaborated on this and wrote that Taz's words are built on Tosafos Pesachim 88a s.v. "sheep of the house," etc. — see there; but according to Ran in Nedarim 36a s.v. "R' Azariah — sheep of the house," etc., there is no need for Tosafos' ruling; he concluded his responsum: we conclude that Heaven forbid to permit a minor to move objects where there is no eruv, etc.] — and see responsa Rabbeinu Akiva Eiger siman 15 and responsa Ketav Sofer siman 77:`,
  "chokhmat-shlomo:1:_": `Seif 1 — from the Torah one is not liable, etc. Note: a new book reached me called responsa Maharam Mintz by the great Gaon R' Moshe Mintz ztz"l, Av Beit Din of Old Ovin; I saw there responsum 2 where a scholar challenged him on the Mishna in Kerisos "there is eating of one eating" — R' Meir said even if it were Shabbat and one removed it in his mouth he is liable; they said to him it is not the language of Scripture; the scholar challenged from Shabbos chapter HaMitzniyot where the Gemara says "everything fit to store" — excluding asherah wood; Rashi: because benefit is forbidden; the difficulty: if so, notar is also forbidden in benefit — why is he liable for removing it? Perforce there it is different because they ate it and Scripture considered it — if so here it is not the language of Scripture, end. Even if this difficulty may be dismissed simply as the book's gloss writes there — in my humble opinion there is no need, for notar has no similarity to idolatry: regarding idolatry, since it is among the buried, it may be burned by anything; thus on Shabbat one may do so; though Rashi Beitza 24a wrote the Merciful One considered its burning — we wrote in one responsum that this is specifically for notar which is burning; if he burns it by another means it is in place of burning, therefore "the Merciful One considered it"; but the buried — since the Torah did not specify in what to burn them, "the Merciful One considered it" does not apply; he may burn on Shabbat; even if he cannot burn, he may tell a non-Jew to burn; though there is no agency for a non-Jew, here we do not require agency since it is in his power in every way — telling a non-Jew is in his power and is like feeding dogs or a non-Jew; certainly permitted to throw into the sea, which is shvus within shvus and permitted where there is a mitzvah; if so here he can burn on Shabbat and fulfill the mitzvah — why store it? Therefore it is not fit to store; but notar, which is specifically burning — on Shabbat he cannot burn; via a non-Jew also not, not to mention rabbinically as one shvus, but also from the Torah it does not help since there is no agency for a non-Jew; he cannot fulfill burning by mitzvah; telling a non-Jew is not burning; he must store to fulfill burning on a weekday; therefore on Shabbat it is fit to store to fulfill the mitzvah later, therefore liable even without eating; proof from what is written there in Shabbos excluding idolatry or menstrual blood — why not say kodashim and notar? Perforce this is fit to store as above — and enough:`,
  "chokhmat-shlomo:2:_": `There seif 2 — sea and valley are two types of karmelit and permitted to move from one to the other, etc. Note: apparently this is not understood — if it is one karmelit, all the more so it would be permitted to move from one to the other within four amot, for such is the law in karmelit. To say he spoke by way of abundance — "even though there are two karmeliyot it is permitted" — is not the implication of his language. Therefore it appears the intent is they do not combine for four amot, and it is permitted to move objects in each within its four amot; even if combined they are more than four amot, they do not combine since each is a domain by itself, and one may move in both up to eight amot; but if it were one karmelit it would be forbidden more than four amot, as appears to me — and I have no time to examine whether the later authorities noticed this:`,
  "eliyah-rabbah:1:_": `(1) [Levush] One who walks, etc. — and for this reason Bach and She'erit Knesset HaGedolah permitted ab initio to remove from reshut ha-yachid and pass in his foot via reshut ha-rabbim and place it in makom patur; but Taz forbids ab initio because of degrading Shabbat; and likewise from reshut ha-yachid to reshut ha-yachid via reshut ha-rabbim:`,
  "eliyah-rabbah:2:_": `(2) And some permit. And it appears that if not so it would be a decree upon a decree (Olat Shabbat). And it requires study, for many times we find decree upon a decree — see end of siman 349 and siman 308 seif 40; and similarly Magen Avraham siman 308; and see siman 355 seif 3 in the gloss; and Rabbeinu Yerucham daf 96 implies his view is to forbid — he wrote at first in the name of Rif to permit, and concluded: but Ra'avad and Razah in Tosafos and Rosh forbade — end; and Beit Yosef wrote Maggid and Rashba and Tur forbade, and so ruled Shiltai Giborim and Riaz chapter 18. I also saw in Olat Shabbat siman 372 — these are his words: "One wonders about Shulchan Aruch who wrote a dispute in a place of three amot — Rif, Rambam, and Rosh permit" — end; and one wonders at his wonder, for Rosh forbids as he wrote in the name of R' Yehuda, and so Beit Yosef wrote, and he himself in this siman:`,
  "eliyah-rabbah:3:_": `(3) [Levush] They permitted to remove, etc. Thus Beit Yosef raised because the Maggid wrote in the name of Rashba that this is his leaning view — end; and Knesset HaGedolah wrote: our master did not analyze that the Maggid did not write Rashba leans but Rambam who forbids; and one may still wonder on Beit Yosef that the Maggid did not mention [Rabbeinu Tam's] view at all — end. And it is wondrous on him that the Maggid explicitly wrote in chapter 16 law 2: "Rambam forbids on dry land but Tosafos permit; and they permitted from here to a garden," etc.; and Rashba wrote his view leans toward the permissive — end; so he mentioned Tosafos who permit; also his intent is clear that Rashba leans toward permitting. I again examined Maimoni with Hagahot — there it does not write "but Tosafos permit"; if so one must say he did not examine the version in Kesef Mishneh that this text was before Beit Yosef. And I say it is clear there is a scribal error in Maimoni with Hagahot and those words are missing — "but Tosafos," etc.; if not, how does he conclude on Rambam "and they permitted from here to a garden," etc. — for Rambam forbids on dry land and this permission is only for Tosafos? Rather certainly those words are missing in the edition and one must say as printed in Kesef Mishneh. Another clear proof: Rashba in Sefer Avodat HaKodesh 17b explicitly wrote his view leans toward permitting — from this the wonder on Knesset HaGedolah is greater. I also saw in responsa Mahari Weil part 3 siman 48 that he erred here, writing Rashba leans to Rambam and forbids — but it is not so; he left me room:`,
  "kaf-hachayyim:1:_": `A) [Seif 1] From the Torah one is liable only for hotza'ah, etc. — that is when he removes an object with his feet from reshut ha-yachid to reshut ha-rabbim or inserts from reshut ha-rabbim to reshut ha-yachid, or stands in reshut ha-yachid and throws or passes to reshut ha-rabbim or the reverse — R' Zalman, note 1; and see below note 18:`,
  "kaf-hachayyim:2:_": `B) There. And the Sages forbade from karmelit to reshut ha-yachid, etc. — a decree because of from reshut ha-yachid to reshut ha-rabbim. Tur. Taz s.k. 1:`,
  "kaf-hachayyim:3:_": `C) There. And the Sages forbade from karmelit to reshut ha-yachid, etc. — karmelit from the Torah is makom patur, and the Sages were stringent with it with the stringency of reshut ha-rabbim and reshut ha-yachid; and rabbinic karmelit — karpef and a tel more than beit se'ah — from the Torah full reshut ha-yachid and rabbinically is like karmelit. Machatzit HaShekel note 1; and see below seif 3:`,
  "machatzit-hashekel:1:א": `Shulchan Aruch seif 1 — but one standing in reshut ha-rabbim, etc. — Taz s.k. 2:`,
  "machatzit-hashekel:1:ב": `(Magen Avraham s.k. 1) Karpef — from the Torah it is full reshut ha-yachid; what they permitted to move objects from it to karmelit — see the reason in Taz s.k. 3 and so in the Gemara:`,
  "machatzit-hashekel:3:א": `(s.k. 3) Two partitions, etc. — for we require attached, meaning like a gamma; but one opposite the other — we do not say "the edge of the roof descends and seals":`,
  "machatzit-hashekel:3:ב": `And it is possible Rama's view is to be stringent — meaning that by the law, even with two partitions opposite one another we say "the edge of the roof descends and seals"; but later siman 361 he is stringent ab initio not to say it to permit moving objects except when attached as Rosh wrote; but here, on the contrary, the stringency is the reverse — even without attachment we say it and forbid moving objects from it to the garden or to karmelit:`,
  "machatzit-hashekel:3:ג": `See above siman 364 seif 2 and Magen Avraham there s.k. 2 whether the door is considered a partition:`,
  "machatzit-hashekel:3:ד": `And Maharil, etc., as R' Chananel wrote, etc. — because responsum Maharil is not before me; in my humble opinion his words are understood thus: in tractate Eruvin 94b it appears Shmuel was told we say "the edge of the roof descends and seals," and the Gemara challenges from what was stated regarding a portico in a valley — Rav said permitted to move throughout; Shmuel said one moves only within four amot; Rashi: a standard portico is a roof built on four pillars; Rav said "the edge of the roof descends and seals," therefore permits moving; Shmuel does not need it, therefore forbids moving except within four amot like a valley which is karmelit; they answer: it is not needed with four, with three it is needed. Such is Rashi's text — meaning specifically a portico that has no partition at all; Shmuel's view is that in such a case we do not say "the edge of the roof descends and seals"; but with three, meaning if it has one partition, we say on the other three partitions "the edge of the roof descends and seals"; but R' Chananel, Rabbenu Tam, Rosh, and most poskim read: it is not needed with three, but with four it is needed. Meaning: specifically with three — when there are only two partitions — Shmuel's view is we do not say "the edge of the roof descends and seals"; but with four he meant when there are three complete partitions and on the fourth partition there are two lechis, Shmuel agrees we say it. In such a case Shmuel's words here are R' Chananel's intent toward Maharil; nevertheless we rule like Rav in prohibitions. I saw this raised in Sefer Teshuvah; perhaps he means to be stringent like Razah whom Rosh brought there — two versions: the first version holds with ten — meaning breach ten amot wide — all agree we say "the edge of the roof descends and seals"; where they disagree is more than ten; and some say more than ten — all agree we do not say it; where they disagree is ten; Rosh wrote: Razah ruled like the latter version, for it appears with scribes one follows the lenient — end; and we rule later siman 361 like Rosh who ruled like the first version that even more than ten Rav holds we say it; if so one may say Maharil ruled for law or was stringent like Razah whom we rule like the latter version — they only disagree regarding ten, but more than ten Rav agrees with Shmuel; and Shmuel's view regarding ten is likewise Rav's view regarding more than ten; and since he was stringent like R' Chananel that for Shmuel three partitions are required and on the fourth two lechis — the same law for Rav regarding more than ten (though R' Chananel himself does not hold like Razah, as Rabbeinu Yehuda wrote siman 362 in the name of Semag — see there; nevertheless Maharil was stringent like both); and the practice of Maharil was that the breach was wider than ten, or that is the default; therefore Maharil needed three partitions and on the fourth side two lechis and a doorway form; for us we make a doorway form in every case, as explained later siman 363 seif 26 in the gloss:`,
  "machatzit-hashekel:3:ה": `And even with three we say "the edge of the roof descends and seals" — meaning when there are only two partitions we say on the third "the edge of the roof descends and seals"; but Rosh added that in any case those two partitions must be attached like a gamma; and it is a great stretch to say Maharil was stringent like Shmuel, for there is no posek who ruled like Shmuel, for the rule is the halacha follows Rav in prohibitions (see Tosafos Gittin 62b s.v. "and now," etc.); I saw this raised in Sefer Teshuvah; perhaps he means to be stringent like the view of Razah, etc.:`,
  "machatzit-hashekel:3:ו": `And if the protrusion has. Meaning the awning has no partition at all except at the end of the awning outward — the awning stands on two pillars; but toward the alley it does not stand on pillars; if so outward there is a doorway form for the awning on two pillars; therefore Magen Avraham wrote one should also make for the side of the house on the protrusion two poles and it will have a doorway form on three sides; on the fourth side a doorway form is not needed, for there are partitions and the house opening; Magen Avraham holds this suffices in all partitions and we do not require complete partitions:`,
  "machatzit-hashekel:3:ז": `And the matter of siman 362 seif 10 — meaning for Rambam regarding breach more than ten a doorway form does not help:`,
  "machatzit-hashekel:3:ח": `And if many houses stand one after another. Meaning they stand side by side — many houses by way of example from east to west; each house has a protrusion as above standing on pillars:`,
  "machatzit-hashekel:3:ט": `That in this correction, etc. — meaning that correction Magen Avraham wrote to make for one house that should have on the protrusion two pillars standing near the house also two poles — this suffices for all the houses; that is, in the first house standing on the east side he places a pole under the protrusion near the house on the eastern side; on the western side of that house he need not place a pole, for in any case it now has a doorway form on two sides — toward the pillars and the eastern side via the pole placed near the house; afterward he places a pole near the last house standing in the west on the western side of the house — thus the other house also has a doorway form on two sides, one toward the pillars and one toward the west via the pole; and a third wall exists for all the houses and their doors behind the protrusion; the houses are connected together; if so all the houses have three partitions and also a fourth wall via the doorway form of the pillars; if they make an eruv together they are considered one and permitted to move objects via this correction:`,
  "magen-avraham:3:א": `Karpef. From the Torah it is full reshut ha-yachid:`,
  "magen-avraham:3:ב": `Two partitions. And regarding the third we say "the edge of the roof descends and seals":`,
  "magen-avraham:3:ג": `Two partitions. It requires study, for in siman 361 it is ruled that attached one to the other is required; and if the door is considered a third partition, then one partition from the side suffices — it requires study; and it is possible Rama's view is to be stringent ab initio — see siman 364 seif 2; and Maharil siman 115 wrote it is good to be stringent as R' Chananel wrote — if it has three partitions, to make lechis on the fourth side via a pole and it will be a doorway form — end; if the protrusion has pillars one should make from the side near the house also one pole from this and one from that and it will be a doorway form on all three sides; and the matter of siman 362 seif 10; and if many houses stand one after another, this correction in two houses standing at the ends suffices if they eruv together:`,
  "magen-avraham:3:ד": `And a lintel four wide. And in an alley opening: even if it is not entirely roofed, only the outer half is roofed, we say "the edge of the roof descends and seals" since there is a place of four from the edge of the roof to the door — the alley is upon it and combines with the alley and the beam permits it; and if the opening is open, even if there is no place of four it is considered inward; but in a house there is no distinction between open and closed opening, for a beam does not permit the house unless four wide; and if two beams are adjacent less than thirty-three [tefachim] they combine to four — see Gemara and Rosh; and if the door is between them, when open it is inward, when closed it is outward:`,
  "mishnah-berurah:1:א": `(1) And passing — that is when his body stands in one domain and he passes the object in his hand to another domain; and see below siman 347 in Mishna Berurah s.k. 8 regarding passing from reshut ha-yachid to reshut ha-yachid via reshut ha-rabbim:`,
  "mishnah-berurah:1:ב": `(2) And the Sages forbade, etc. — for it resembles reshut ha-rabbim somewhat, for it lacks partitions; nevertheless it is not reshut ha-rabbim, for it is not made for public passage; therefore they decreed on it not to remove and insert from it to reshut ha-rabbim or reshut ha-yachid, lest they come to permit even from reshut ha-yachid to reshut ha-rabbim:`,
  "mishnah-berurah:1:ג": `(3) Permitted to remove and insert — and the same for passing and throwing:`,
  "mishnah-berurah:1:ד": `(4) But one standing — meaning he was standing and walked and removed or inserted, or remained standing but passed or threw:`,
  "mishnah-berurah:1:ה": `(5) Liable — since he performed akirah in reshut ha-yachid and hanachah in reshut ha-rabbim or the reverse, we do not care what he transferred via makom patur in between; and specifically if he did not stand in makom patur; but if he stood there briefly and then returned and removed to the other domain — exempt, since he performed hanachah in makom patur; nevertheless there is a rabbinic prohibition even in this, for they decreed lest he come to be lenient and explicitly remove from reshut ha-yachid to reshut ha-rabbim; and the same — forbidden to remove for this reason from reshut ha-yachid to makom patur via reshut ha-rabbim even if he will be careful not to stand in reshut ha-rabbim:`,
  "mishnah-berurah:1:ו": `(6) And similarly one should not stand, etc. — this "and similarly" is not precise, for there is no liability here [since he himself stands and rests in makom patur — when the object reaches him it is as if he placed it there briefly]; and he wrote "and similarly" because of the prohibition, since in any case through him removal from reshut ha-yachid to reshut ha-rabbim is done and he may come to be lenient to remove from reshut ha-yachid to reshut ha-rabbim explicitly:`,
  "mishnah-berurah:1:ז": `(7) And take an object from the hand, etc. — and the same to take from reshut ha-yachid ground and give to reshut ha-rabbim ground:`,
  "mishnah-berurah:1:ח": `(8) And to exchange, etc. — meaning he stands on makom patur and takes from the hand of one standing in reshut ha-yachid and gives to one standing in karmelit or the reverse; and the same if he takes an object from reshut ha-yachid and places it in makom patur and returns and takes from makom patur and places it in karmelit:`,
  "mishnah-berurah:1:ט": `(9) Some say — they hold there is no distinction between Torah domains and rabbinic domains for this matter:`,
  "mishnah-berurah:1:י": `(10) And some permit — they hold that specifically in Torah domains they decreed, not in rabbinic domains, for that would be a decree upon a decree:`,
  "mishnah-berurah:2:א": `(11) Passing four amot — that is via akirah and hanachah; and there is rabbinic prohibition via akirah or hanachah alone, as below siman 347:`,
  "mishnah-berurah:2:ב": `(12) In karmelit — for it resembles reshut ha-rabbim, as above; and see below siman 349 seif 5 and Mishna Berurah there:`,
  "mishnah-berurah:2:ג": `(13) Two types, etc., and permitted, etc. — meaning nevertheless permitted to move objects from one to the other, and they did not decree because of domains:`,
  "mishnah-berurah:3:א": `(14) More than beit se'ah — and the measure of beit se'ah is explained below siman 358: seventy amot and four tefachim by seventy amot and four tefachim in square:`,
  "mishnah-berurah:3:ב": `(15) That was not enclosed for dwelling — such as if his intent was to plant or sow and the like, as explained below siman 358:`,
  "mishnah-berurah:3:ג": `(16) The Sages forbade, etc. — since it is so large they may confuse it with reshut ha-rabbim, and the Sages made it like karmelit:`,
  "mishnah-berurah:3:ד": `(17) And permitted, etc., to another karmelit — even though from the Torah it is reshut ha-yachid for all matters since it has partitions, and one who throws from it to reshut ha-rabbim is liable, and from reshut ha-yachid to karmelit — behold it is forbidden to remove, as above — nevertheless here they permitted, for if we forbid this they will think it is full reshut ha-yachid and there is no karmelit upon it at all, and they will come to move objects throughout it like other reshut ha-yachid; and through this others will come to move objects also in reshut ha-rabbim, for this resembles reshut ha-rabbim somewhat since it is large and was not enclosed for dwelling; therefore the Sages gave it the law of other karmelit for this matter — permitted to remove from it to another karmelit such as a valley and the like:`,
  "mishnah-berurah:3:ה": `(18) Therefore permitted to take, etc. — for even though the garden is reshut ha-yachid from the Torah since it is enclosed by partitions, since rabbinically they made it like karmelit they did not forbid moving objects from it to the valley before it; the reason as above:`,
  "mishnah-berurah:3:ו": `(19) To open, etc. — meaning even to insert the garden door with the key inward:`,
  "mishnah-berurah:3:ז": `(20) That there not be between them, etc. — meaning at the garden opening there should not be a threshold (called "schwell") ten high upon which there is reshut ha-yachid there, for then it is forbidden to insert the key or remove it, for he moves objects from karmelit to reshut ha-yachid and from reshut ha-yachid to karmelit:`,
  "mishnah-berurah:3:ח": `(21) That it is ten high — for otherwise the threshold itself is karmelit and like a valley; and if it were not four wide it is makom patur, and certainly permitted to stand on it to open and close:`,
  "mishnah-berurah:3:ט": `(22) Two partitions, etc. — and the third is made via the lintel, for we say "the edge of the roof descends and seals":`,
  "mishnah-berurah:3:י": `(23) That they are four wide — for in less than this, even four complete partitions are not reshut ha-yachid, as above siman 345 seif 9:`,
  "mishnah-berurah:3:כ": `(24) That it is not ten high — meaning the threshold; and the same when it is not three high or there is no threshold at all — reshut ha-yachid is made via the partitions:`,
  "mishnah-berurah:3:ל": `(25) From the threshold to reshut ha-yachid — this does not refer above where the threshold stands before the garden; rather the threshold of the house standing under the lintel — and he informs us that even if the lintel upon it is four wide so there is reshut ha-yachid there, as above, nevertheless one should be stringent not to insert from that place to the house or the reverse, lest sometimes the lintel not be four wide and he will do so anyway:`,
  "mishnah-berurah:3:מ": `(26) For we are concerned perhaps not, etc. — and the same — forbidden to remove from the threshold to reshut ha-rabbim even if it is not four wide, lest it happen the lintel is four and then it is full reshut ha-yachid (there in Mordechai):`,
  "mishnah-berurah:3:נ": `(27) The law of that before it — if it is reshut ha-rabbim this place is nullified relative to it and also becomes reshut ha-rabbim; if karmelit, karmelit:`,
  "mishnah-berurah:3:ס": `(28) And even if three high — meaning then that place is makom patur, for presumably since the lintel on the threshold is not four wide, the doorposts from the sides and the threshold itself are also not four wide, and it becomes makom patur; and from makom patur we hold it is permitted to move objects to reshut ha-yachid and reshut ha-rabbim; nevertheless, since all our domains are karmelit according to many poskim and this threshold is adjacent to it, we say "a kind found its kind," etc.; and there is no distinction in all this between the house door open or closed — always forbidden to insert from the threshold inward [Magen Avraham]. And behold according to what is explained in this gloss one must be careful in those places where moving objects is forbidden for lack of an eruv, and the synagogue door faces the street with no room before the door, and a non-Jew brings the key — the shamash should not take the key from his hand until he is with the non-Jew together under the lintel over the door, lest there be four in the roof and it be reshut ha-yachid and he move from karmelit before the synagogue into reshut ha-yachid; therefore he should take the key from the non-Jew under the lintel, then open the lock, and not open the door until he removes the key, then open — lest there not be four in the roof outside the door, in which case it is karmelit and he inserts from karmelit to reshut ha-yachid; therefore he should first remove the key and give it to the non-Jew or hide it in the bottom of the threshold or above before the door closes [and it is fitting for the congregation to make some room before the door that is reshut ha-yachid and have the non-Jew bring the key there, otherwise it is hard to limit that both stand in such a short place]; and one must be careful not to move objects from the house outward when open to karmelit only to where the door closes and no more, lest the outer part of the threshold outside the door not be four and it be karmelit and he move from reshut ha-yachid to karmelit (Taz):`,
  "mishnah-berurah:3:ע": `(29) And similarly if the roof — like what is common on roofs before shops where they extend beams outward and cover them with boards:`,
  "mishnah-berurah:3:פ": `(30) Its law is like the domain before it — therefore forbidden to insert from it inward since it has no partitions; regarding removing outward — if karmelit were at its side it is permitted; if reshut ha-rabbim were at its side, forbidden to remove, since being roofed it has the law of karmelit, as above siman 345 seif 14:`,
  "mishnah-berurah:3:צ": `(31) And similarly regarding roofs, etc. — Taz wrote here is explained the doubt many people are uncertain about: a house before which toward the street a roof protrudes toward the street called in foreign tongue "perliban" — what is their law, whether one may move objects there from the house; many err saying the protruding roof "descends and seals" and it is as if built to the ground; from here it is explicit that the law of what is under the roof is like the domain before them — see there; and so all the later authorities. What is their correction: if the roof protrusion has pillars toward the street, place poles aligned with them also toward the houses and the roof upon them will have the law of a doorway form; thus there is a doorway form on all three sides; and if they are of many houses standing one next to the other, one need not do this for every house — make this correction in two houses standing at the two ends; but they must make an eruv chatzerot together, and then permitted to insert and remove from the houses under the roofs and vice versa [later authorities]; in every case forbidden to insert and remove from reshut ha-rabbim under the roofs and vice versa [Chayei Adam] — that is when the protrusion was four tefachim wide, for then there is karmelit law on the area beneath; and see Chayei Adam general rule 53 seif 14 what he wrote further regarding gangways adjacent to inns where the roof rests on pillars:`,
  "peri-megadim:1:א": `And the Sages — Taz. Karmelit from the Torah is makom patur, and the Sages were stringent with it with the stringency of reshut ha-rabbim and reshut ha-yachid; and rabbinic karmelit — karpef and a tel more than beit se'ah — from the Torah full reshut ha-yachid and rabbinically like karmelit; see s.k. 3 and Magen Avraham 1; and see openings of karmelit in siman 345 seif 17 not open like karmelit here in karpef they are like reshut ha-yachid:`,
  "peri-megadim:1:ב": `And know that passing from reshut ha-yachid to reshut ha-rabbim is a type of hotza'ah and hachnasah; however passing from reshut ha-yachid to reshut ha-yachid with reshut ha-rabbim in the middle that one is liable for is mentioned at the beginning of HaZorek; and in Rambam chapter 13 law 18 — even above ten it is implied, all the more below ten; and Rashi Shabbos 2b s.v. "throwing" from passing, etc.; and in Tosafos there 3 s.v. "in making it" in the name of Yerushalmi chapter HaZorek — passing from reshut ha-yachid to reshut ha-yachid with reshut ha-rabbim in the middle one is liable only if the passer passed into his friend's hand; if he passed over reshut ha-yachid alone — exempt; all the more when his friend receives from him — see there; and in Rambam nothing of this is mentioned. And there is room to doubt whether they decreed passing from reshut ha-yachid to reshut ha-yachid via rabbinic karmelit above ten — one may say passing above ten is a novelty as Chiddushei HaRashash — "you have in it only its novelty" — and the Rabbis did not decree; and even below ten; and in Chiddushei I wrote passing below ten even though it is not a novelty — nevertheless between two balconies exempt, for it is enough that it comes from the law to be judged — we derive from above ten that was in the Mishkan. Passing four amot and throwing four amot in reshut ha-rabbim — halacha was learned; they made a fence for karmelit; and even though one may say the Sages expounded from "guard" to "guard" in Written Torah, not Oral Torah — this is not called Oral Torah, as Ran wrote chapter 23 in Mishna Avot — melachot: passing is included in hotza'ah — see there; and in Magen Avraham we wrote from this:`,
  "peri-megadim:2:_": `But — Taz. His words require explanation: in Bach it appears the distinction of one standing in reshut ha-yachid who removes to reshut ha-rabbim via makom patur who remained standing in reshut ha-yachid and inserts or removes or passes to his friend's hand or throws — liable (and we learn that "caught" — even the object sees the air of the ground in throwing is not like placed in makom patur); and Tur's text before this distinction has another distinction: provided he does not remove from reshut ha-yachid to makom patur and transfer from makom patur to reshut ha-rabbim — three distinctions: the first two for liability — first walking with his feet is not like standing; second standing in place and removing, passing to friend's hand or throwing — "caught" is not like hanachah and he is liable; and from case 1 we do not hear that walking and the object via him does not see the face of makom patur; and third standing in makom patur and removing from reshut ha-yachid to reshut ha-rabbim — exempt but forbidden; but Beit Yosef explained according to this version from reshut ha-yachid to reshut ha-rabbim via makom patur — he stood in makom patur; in case 1 also exempt but forbidden, as this law is written in the third case; and placing his body is like placing the object; and forbidden, for it appears as uprooting his hand did not rest; in case 1 greater novelty — even though he rested in makom patur and afterward uprooted from there body and hand — forbidden, for it degrades Shabbat; for Bach and Taz this was not placed: if so the order should be second case first, then third, then first — in both exempt but forbidden (Avodat HaKodesh); and for Taz even Bach's explanation was not placed: in case 1 it is the second case per his explanation — standing, he did not remain there. And behold from reshut ha-yachid to makom patur via reshut ha-rabbim to permit ab initio is difficult from the Mishna like siman 347 — akirah without hanachah ab initio forbidden; to say in the Mishna melacha was done between them — from where? And one may say a fortiori akirah alone forbidden, or rabbinically in such a case; and Beit Yosef wrote perhaps he will stand to relieve himself and be liable — rabbinically; and one decree; or one may say for one relieving his objects from a corner and reconsidered — exempt, for one akirah is not akirah at all; unlike here he intended to uproot from reshut ha-yachid in any case, for he rested in reshut ha-rabbim — possibly liable; or perhaps sometimes he will intend to uproot from reshut ha-yachid and relieve himself in reshut ha-rabbim; and what is written in siman 308 there — throwing from reshut ha-yachid to reshut ha-yachid with reshut ha-rabbim in the middle — there he is not walking, so why permit? And one may say; and in the end Taz raised that the old version is primary in Tur: in case 1 for liability in walking, not like standing; second for liability in standing who remained in reshut ha-yachid and removes or inserts to reshut ha-rabbim via makom patur; and he explains hotza'ah and hachnasah whether by passing or throwing; and "caught" even though it sees the face of the ground is not like hanachah (see beginning of Shabbat) in this; nevertheless the main law he agreed with Beit Yosef to forbid rabbinically in removing from reshut ha-yachid to makom patur via reshut ha-rabbim; and possibly throwing thus is also forbidden — it is discussed in siman 347 and 308; here one cannot elaborate:`,
  "peri-megadim:3:_": `That was not — Taz. Eruvin 67b; and see Tur and Beit Yosef; and this karpef without roofing is permitted and does not come to be confused with reshut ha-rabbim; and it appears specifically to another karmelit it is permitted; to reshut ha-rabbim liable and to reshut ha-yachid forbidden rabbinically — see siman 345 and 372 seif 1; Beit Yosef there explains thus from karpef more than beit se'ah to a courtyard forbidden — see there:`,
  "rabbi-akiva-eiger:1:_": `Magen Avraham s.k. 4 — there is no place of four, it is inward; and if the beam is not as wide as the opening and is placed toward the inside — Rashi's view forbids moving objects from the edge of the beam outward; and in Razah he wrote to permit:`,
  "turei-zahav:1:א": `And the Sages forbade, etc. — a decree because of from reshut ha-yachid to reshut ha-rabbim:`,
  "turei-zahav:1:ב": `But one standing in reshut ha-rabbim or removes, etc. — this "or" is a scribal error and should read "and removes"; so too Tur; and explanation is required for what he wrote afterward "or passes," for the first part also deals with passing — perforce "one standing in reshut ha-yachid" does not mean he remained standing but that he was standing and walked and removed or inserted, or remained standing but passed or threw; Beit Yosef wrote that before this distinction it was written in his book: provided he does not remove from reshut ha-yachid to makom patur via reshut ha-rabbim; he wrote on this: even though below he ruled walking is not like standing, and if so since he did not stand to relieve himself in reshut ha-rabbim he removes from reshut ha-yachid to makom patur which is permitted — nevertheless, since if he stood in reshut ha-rabbim he would be liable, they decreed lest he stand; in the old book it reads: provided he does not remove from reshut ha-yachid to makom patur and transfer via makom patur to reshut ha-rabbim or the reverse — end; difficulty on this: if so what did Tur write afterward "and similarly one standing in reshut ha-yachid," etc. — perforce meaning walking from reshut ha-yachid via makom patur to reshut ha-rabbim as he wrote; if so it is the first case; for Beit Yosef's version this works; Maharshal wrote on this version it is mistaken, for we do not find this decree "lest he stand to relieve himself"; and according to the law it is permitted ab initio to remove from reshut ha-yachid and pass in his foot via reshut ha-rabbim and place in makom patur — his words are very astonishing, for certainly this decree is included in what the Gemara says: provided he not take from a homeowner and give to a poor person, for he degrades Shabbat prohibitions ab initio to cause hotza'ah from reshut ha-yachid to reshut ha-rabbim — decree lest he come to be lenient and explicitly remove from reshut ha-yachid to reshut ha-rabbim — end; and here too this decree applies; and further, a clear proof to forbid this: if we permit from reshut ha-yachid to makom patur via reshut ha-rabbim because walking is not like standing, we would also permit reshut ha-yachid to reshut ha-yachid via reshut ha-rabbim, since there is no standing in reshut ha-rabbim and akirah and hanachah would be from reshut ha-yachid to reshut ha-yachid; in siman 308 Tur explains this is forbidden; plainly even though walking is not like standing for liability, for permission it is certainly forbidden in every case because of degrading Shabbat — Heaven forbid to say any permission here; nevertheless difficulty on Beit Yosef's version, for we do not find this explicitly in the Gemara; and the cases Tur wrote afterward are explicit; it would have been better to precede what is explicit in the Gemara; therefore it appears that even though by law one should forbid even in Beit Yosef's case, nevertheless Beit Yosef's old version is primary; and what he wrote afterward "or passes" must be explained: he means removing and inserting whether via passing or throwing, as appears to me:`,
  "turei-zahav:3:א": `That was not enclosed for dwelling. From the Torah it is full reshut ha-yachid for all matters; they only permitted moving objects from it to karmelit, for if this were forbidden they would say it is full reshut ha-yachid and come to move objects throughout it; and through this others would come to move objects in reshut ha-rabbim, for this resembles reshut ha-rabbim; and even though now he also violates a rabbinic prohibition in moving from reshut ha-yachid to karmelit, nevertheless they did not forbid this, for it is not common and the Rabbis did not decree on it:`,
  "turei-zahav:3:ב": `Therefore permitted to take, etc. — for even though the garden is reshut ha-yachid from the Torah, they did not forbid moving objects from it to karmelit — and this is exactly the law stated above:`,
  "turei-zahav:3:ג": `For then it is reshut ha-yachid. Meaning forbidden to insert there from the karmelit before it; if so it would be fitting to permit inserting from this threshold to reshut ha-yachid; nevertheless forbidden, lest it not be four wide and it will be karmelit; even if not four wide, since karmelit is before it — "a kind found its kind," etc.; and what he wrote "like reshut ha-yachid" — this "like" is a scribal error:`,
  "turei-zahav:3:ד": `However forbidden to insert, etc. — in Hagahot Mordechai first chapter of Shabbat he wrote: our threshold — what is from the door inward when closed is full reshut ha-yachid; what is outside the door — forbidden to insert from upon it inward, for there is no analysis now in the awning, for we have no awning four wide; and the analyzer lest he violate a Torah prohibition; and even forbidden to remove from upon it outward, lest the roof be four and it be forbidden to remove from the Torah outward — end. Beit Yosef in the name of Kolbo wrote a person cannot stand in reshut ha-rabbim or karmelit and lock a house and insert the key inward under the door or above from the sides, for even a little is forbidden to insert and remove from domain to domain — end; Mordechai first chapter of Shabbat wrote: when a minor brings a key with him it is permitted to take the key and open, since the lintel does not protrude four in reshut ha-rabbim it is like reshut ha-rabbim; but after opening the lock he must remove the key before opening the door itself, for what is from the door inward is full reshut ha-yachid — end. I copied all this because I have seen many stumble in those places where moving objects is forbidden for lack of an eruv, and the synagogue door faces the street with no room before the door and a non-Jew brings the key — be careful the shamash not take the key from his hand until he is with the non-Jew under the lintel over the door, lest there be four in the roof and it be reshut ha-yachid and he move from karmelit before the synagogue into reshut ha-yachid; therefore take the key from him under the lintel, then open the lock, and do not open the door until he removes the key, then open the door — lest there not be four in the roof outside the door, in which case it is karmelit and he inserts from karmelit to reshut ha-yachid; therefore first remove the key and give it to the non-Jew or hide it in the door at its bottom or side; and a house whose door opens to karmelit must be careful not to move objects from the house outward except to where the door closes and no more, lest the outer part not be four and it be karmelit and he move from reshut ha-yachid to karmelit; fitting for that congregation to make some room before the door that is reshut ha-yachid and have the non-Jew bring the key there, and then no concern; and it is implied in Mordechai that there is permission to bring via a minor the key like via a non-Jew; and even though chapter Cheresh says keys were lost and R' Pedas told a minor to go there and he will find it — implying forbidden to do via having the minor bring there, as we say there one should not pile in hands — there it deals with reshut ha-rabbim which is from the Torah; but we have only karmelit which is rabbinic, as appears to me:`,
  "turei-zahav:3:ה": `And similarly in our gardens protruding, etc. — here is explained the doubt many are uncertain about: a house before which toward the street a roof protrudes toward the street built underneath with boards called in foreign tongue "perliban" — what is their law, whether one may move objects there from the house; many err saying "the edge of the roof descends and seals" to there and the side protruding toward the street, and it is as if built to the ground; from here it is explicit that the law of what is under the roof is like the domain before them; and so in Beit Yosef in the name of Shiltei Giborim in a responsum he copied — end: and if there are beams or pillars standing toward the houses open to reshut ha-rabbim under that awning over the house openings — behold these may not raise and lower; and when we say "remnants of a store," etc. — but from reshut ha-yachid to reshut ha-rabbim even via a pole is forbidden, all the more if between the beams and pillars opposite the house openings there is more than thirty-three, etc.; and that which he wrote reshut ha-yachid to reshut ha-rabbim — the same for karmelit, for he only distinguishes regarding making karmelit thereby — see there; and he wrote further there: consider for yourself if reshut ha-rabbim were roofed whether there is any benefit at all — a roof has no benefit for Shabbat prohibition; one who removes from the house opening outward — it is clear "the edge of the roof descends and seals" does not apply here; and it is a simple matter that even under the awning of the threshold as above we do not say so — how much more before the opening; the reason we do not say here "the edge of the roof descends and seals" is since there are no partitions from the sides, their law is like the domain before them, as Rama wrote here; and see siman 365 what is written at its end:`,
};

function esc(s) {
  return s.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$/g, "\\$");
}

function emit(obj, name) {
  const lines = ["export const t = {"];
  for (const [k, v] of Object.entries(obj)) {
    lines.push(`  ${JSON.stringify(k)}: \`${esc(v)}\`,`);
  }
  lines.push("};");
  fs.writeFileSync(name, lines.join("\n") + "\n", "utf8");
}

emit(mech, "mech346-en.mjs");
emit(small, "small346-en.mjs");
console.log("mech", Object.keys(mech).length, "small", Object.keys(small).length);
